/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=dealProduct, operation=add
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Add a product to a deal */
export type PipedriveV2DealProductAddParams = {
  resource: 'dealProduct';
  operation: 'add';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the deal to add a product to
 * @default 0
 */
    dealId?: number | Expression<number>;
/**
 * ID of the product to add to the deal
 * @default 0
 */
    productId?: number | Expression<number>;
/**
 * Price at which to add this product to the deal
 * @default 0
 */
    item_price?: number | Expression<number>;
/**
 * How many items of this product to add to the deal
 * @default 1
 */
    quantity?: number | Expression<number>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** Text to describe this product-deal attachment
     */
    comments?: string | Expression<string> | PlaceholderValue;
    /** The value of the discount. The discount type can be specified in discount_type.
     * @default 0
     */
    discount?: number | Expression<number>;
    /** The type of the discount
     * @default percentage
     */
    discount_type?: 'percentage' | 'amount' | Expression<string>;
    /** The tax percentage
     * @default 0
     */
    tax?: number | Expression<number>;
  };
};

export type PipedriveV2DealProductAddNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2DealProductAddParams>;
};